from typing import List

def string_xor(a: str, b: str) -> str:
    # Pad the shorter string with leading '0's to make them of equal length
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation on corresponding bits
    result = []
    for bit_a, bit_b in zip(a, b):
        if bit_a == bit_b:
            result.append('0')
        else:
            result.append('1')

    # Join the list of bits into a string and return
    return ''.join(result)

