    for num in numbers:
        if num in occurrences:
            occurrences[num] += 1
        else:
            occurrences[num] = 1

    # Step 2: Filter the list based on occurrences
    result = [num for num in numbers if occurrences[num] == 1]

    # Step 3: Return the filtered list
    return result

