import math

def is_prime(num: int) -> bool:
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    sqrt_num = math.isqrt(num)
    for i in range(3, sqrt_num + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.

    :param n: The position of the prime Fibonacci number to find.
    :return: The n-th prime Fibonacci number.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    a, b = 0, 1  # First two Fibonacci numbers
    count = 0  # Count of prime Fibonacci numbers found

    while count < n:
        # Check if the current Fibonacci number is prime
        if is_prime(b):
            count += 1
            if count == n:
                return b
        # Generate the next Fibonacci number
        a, b = b, a + b

    return b  # This line is theoretically unreachable given the while loop condition

