def fib4(n: int) -> int:
    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize a list to store the sequence values
    fib4_seq = [0] * (n + 1)
    fib4_seq[0] = 0
    fib4_seq[1] = 0
    fib4_seq[2] = 2
    fib4_seq[3] = 0

    # Compute the sequence iteratively
    for i in range(4, n + 1):
        fib4_seq[i] = fib4_seq[i - 1] + fib4_seq[i - 2] + fib4_seq[i - 3] + fib4_seq[i - 4]

    return fib4_seq[n]

