    # Define the vowels and their replacements
    vowel_replacements = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    # Initialize an empty string to store the encoded message
    encoded_message = ""

    # Iterate over each character in the message
    for char in message:
        # Swap the case of the character
        swapped_char = char.swapcase()

        # Check if the character is a vowel and replace it if necessary
        if swapped_char in vowel_replacements:
            encoded_message += vowel_replacements[swapped_char]
        else:
            encoded_message += swapped_char

    return encoded_message

