def split_words(txt):
    # Check for whitespace and split if found
    if ' ' in txt:
        return txt.split()

    # Check for commas and split if found
    if ',' in txt:
        return txt.split(',')

    # If no whitespace or commas, count lowercase letters with odd order in the alphabet
    count = 0
    for char in txt:
        if char.islower() and ord(char) % 2 == 1:
            count += 1

    return count
