from typing import List
import heapq

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def within_bounds(x, y):
        return 0 <= x < n and 0 <= y < n

    # Priority queue to store paths (path, x, y, length)
    pq = []
    for i in range(n):
        for j in range(n):
            # Start with each cell as the initial path
            heapq.heappush(pq, ([grid[i][j]], i, j, 1))

    while pq:
        path, x, y, length = heapq.heappop(pq)

        if length == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if within_bounds(nx, ny):
                new_path = path + [grid[nx][ny]]
                heapq.heappush(pq, (new_path, nx, ny, length + 1))

    return []  # This line should never be reached given the problem constraints

