def bf(planet1, planet2):
    # Define the order of planets from the closest to the Sun to the farthest
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if both planet1 and planet2 are valid planet names
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Find the indices of planet1 and planet2
    index1 = planets.index(planet1)
    index2 = planets.index(planet2)

    # Determine the range of planets between planet1 and planet2
    start = min(index1, index2)
    end = max(index1, index2)

    # Extract the planets between the two indices (excluding the endpoints)
    between_planets = planets[start+1:end]

    # Return the planets as a tuple
    return tuple(between_planets)

